ruleContent.content:
@js:
var m = result.match(/let code = "([A-Za-z0-9+/=]+)"/);
var url = '';
if (m) {
  var bytes = Packages.android.util.Base64.decode(m[1], 0);
  url = String(new Packages.java.lang.String(bytes, 'UTF-8'));
}
url ? url : baseUrl;

ruleExplore.bookUrl:
@js:
var rid = String(result.attr('data-rid'));
var nm = String(result.select('.result-title').first().text());
var ar = String(result.select('.result-artist').first().text());
'https://higequ.com/player/' + rid + '/?name=' + encodeURIComponent(nm) + '&artist=' + encodeURIComponent(ar);

